    async function closeAndResize(producerId, kind) {
      if (kind === "audio") {
        try {
          let id = `AudioOnly_${producerId}`;
          let audioElement = await document.getElementById(id);
          audioElement.remove();
        } catch (error2) {
        }
        allAudioStreams = await allAudioStreams.filter(function(audioStream) {
          return audioStream.producerId !== producerId;
        });
        if (recordingDisplayType == "video" && recordingVideoOptimized == true) {
        } else {
          let participant2 = await participants.find(
            (obj) => obj.audioID === producerId
          );
          if (participant2) {
            if (participant2.videoID !== null && participant2.videoID !== "") {
            } else {
              activeNames = await activeNames.filter(function(name2) {
                return name2 !== participant2.name;
              });
            }
          }
        }
        let checker2 = false;
        let alt_checker = false;
        if (meetingDisplayType == "video") {
          checker2 = participant[0].videoID != null && participant[0].videoID != "" && participant[0].videoID != void 0;
        } else {
          checker2 = true;
          alt_checker = true;
        }
        if (checker2) {
          if (shareScreenStarted || shared) {
            if (!alt_checker) {
              await reorderStreams();
            }
          } else {
            if (alt_checker && meetingDisplayType != "video") {
              await reorderStreams(false, true);
            }
          }
        }
      } else if (kind === "video") {
        if (producerId == adminIDStream) {
          updateMainWindow = true;
        }
        try {
          allVideoStreams = await allVideoStreams.filter(function(videoStream) {
            return videoStream.producerId !== producerId;
          });
          try {
            oldAllStreams = await oldAllStreams.filter(function(videoStream) {
              return videoStream.producerId !== producerId;
            });
          } catch (error2) {
          }
          try {
            newLimitedStreams = await newLimitedStreams.filter(function(videoStream) {
              return videoStream.producerId !== producerId;
            });
          } catch (error2) {
          }
        } catch (error2) {
          try {
            oldAllStreams = await oldAllStreams.filter(function(videoStream) {
              return videoStream.producerId !== producerId;
            });
          } catch (error3) {
          }
        }
        try {
          activeNames = await activeNames.filter(function(name2) {
            let participant2 = streamNames.find(
              (obj) => obj.producerId === producerId
            );
            return name2 !== participant2.name;
          });
        } catch (error2) {
        }
        if (lock_screen) {
          defer_receive = true;
          if (newLimitedStreamsIDs.includes(producerId)) {
            await prepopulateUserMedia(hostLabel);
            await reorderStreams(false, true);
          }
        } else {
          await prepopulateUserMedia(hostLabel);
          await reorderStreams(false, true);
        }
      } else if (kind === "screenshare" || kind === "screen") {
        updateMainWindow = true;
        shareScreenStarted = false;
        shareEnded = true;
        lock_screen = false;
        firstAll = false;
        first_round = false;
        if (!gotAllVids || defer_receive) {
          defer_receive = false;
          await getVideos();
          await rePort();
        }
        if (eventType == "conference") {
          await moveBoard();
          await $(".maingrid").remove();
          await addTimer();
          let height952 = window.innerHeight * 0.95;
          $(".othergrid").css("height", height952 + "px");
        }
        await prepopulateUserMedia(hostLabel);
        await reorderStreams(false, true);
      }
    }
